// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount) public {
        // Ensure deposit amount is less than MinDeposit (1 ether) to trigger the bug difference
        uint256 minDeposit = c.MinDeposit();
        vm.assume(depositAmount < minDeposit);
        vm.assume(depositAmount > 0);
        vm.assume(withdrawAmount > 0 && withdrawAmount <= depositAmount);

        // Give the user enough ether to deposit
        address user = address(0x1234);
        vm.deal(user, depositAmount);
        vm.prank(user);
        c.Deposit{value: depositAmount}();

        // Now attempt to withdraw
        uint256 balanceBefore = c.balances(user);
        (bool success,) = address(c).call(abi.encodeWithSignature("CashOut(uint256)", withdrawAmount));

        // After CashOut, the property: if a deposit below MinDeposit happened,
        // then the user's balance after withdrawal must be less than MinDeposit
        uint256 balanceAfter = c.balances(user);
        // In the reference, deposit was rejected so balance stays 0; in mutant it was accepted.
        // If the deposit was accepted (mutant), then balanceAfter could be non-zero.
        // The rule: balanceAfter + withdrawAmount < MinDeposit (since total deposited < MinDeposit)
        assertTrue(balanceAfter + withdrawAmount < minDeposit);
    }
}

